#include <stdio.h>
#include <string.h>

#define MAXN 256

/* The tree lives in arrays: node i holds val[i], and its children are
   node numbers (-1 for none). No malloc, no pointers to free. */
int val[MAXN], left[MAXN], right[MAXN], parent[MAXN], depth[MAXN];
int count = 0;
int path[MAXN];      /* values compared on the way down, for the last insert */
int plen = 0;

int new_node(int v, int up, int d) {
    val[count] = v; left[count] = -1; right[count] = -1;
    parent[count] = up; depth[count] = d;
    return count++;
}

/* Insert v below root, walking down and remembering every value compared. */
int insert(int root, int v) {
    plen = 0;
    if (root == -1) return new_node(v, -1, 0);
    int node = root;
    while (1) {
        path[plen++] = val[node];
        if (v < val[node]) {
            if (left[node] == -1) { left[node] = new_node(v, node, depth[node] + 1); return root; }
            node = left[node];
        } else if (v > val[node]) {
            if (right[node] == -1) { right[node] = new_node(v, node, depth[node] + 1); return root; }
            node = right[node];
        } else {
            return root;   /* already there */
        }
    }
}

/* In-order walk: visits values smallest first, so the visit number is the x position. */
int xpos[MAXN];
int next_x = 0;
void walk(int node) {
    if (node == -1) return;
    walk(left[node]);
    xpos[node] = next_x++;
    walk(right[node]);
}

/* ---- insert orders ---- */
unsigned int rng = 1;
unsigned int xorshift(void) {
    rng ^= rng << 13; rng ^= rng >> 17; rng ^= rng << 5;
    return rng;
}

int out_n = 0;
void middle_first(int *sorted, int lo, int hi, int *out) {
    if (lo > hi) return;
    int mid = (lo + hi) / 2;
    out[out_n++] = sorted[mid];
    middle_first(sorted, lo, mid - 1, out);
    middle_first(sorted, mid + 1, hi, out);
}

void make_order(const char *name, int *sorted, int n, unsigned int seed, int *out) {
    if (strcmp(name, "balanced") == 0) {
        out_n = 0;
        middle_first(sorted, 0, n - 1, out);
    } else if (strcmp(name, "random") == 0) {
        for (int i = 0; i < n; i++) out[i] = sorted[i];
        rng = seed;
        for (int i = n - 1; i > 0; i--) {          /* Fisher-Yates shuffle */
            int j = (int)(xorshift() % (unsigned int)(i + 1));
            int t = out[i]; out[i] = out[j]; out[j] = t;
        }
    } else if (strcmp(name, "alternating") == 0) {
        int lo = 0, hi = n - 1;
        for (int i = 0; i < n; i++) out[i] = (i % 2 == 0) ? sorted[lo++] : sorted[hi--];
    } else {
        for (int i = 0; i < n; i++) out[i] = sorted[i];
    }
}

const char *ORDERS[4] = {"balanced", "random", "sorted", "alternating"};

/* Build a tree from an order; returns the root. */
int build(int *order, int n, int print_paths) {
    count = 0;
    int root = -1;
    for (int i = 0; i < n; i++) {
        root = insert(root, order[i]);
        if (print_paths) {
            printf(i ? ",[" : "[");
            for (int k = 0; k < plen; k++) printf(k ? ",%d" : "%d", path[k]);
            printf("]");
        }
    }
    return root;
}

int height(void) {
    int h = 0;
    for (int i = 0; i < count; i++) if (depth[i] + 1 > h) h = depth[i] + 1;
    return h;
}
int total_compare(void) {           /* comparisons to find every value once: depth + 1 each */
    int sum = 0;
    for (int i = 0; i < count; i++) sum += depth[i] + 1;
    return sum;
}

int main() {
    int values[15] = {5, 12, 20, 27, 33, 41, 47, 50, 58, 63, 70, 74, 81, 88, 95};
    int order[MAXN], sorted[MAXN];

    printf("__NB_SET__ {\"key\":\"bst\",\"value\":{\"values\":[");
    for (int i = 0; i < 15; i++) printf(i ? ",%d" : "%d", values[i]);
    printf("],\"trees\":[");
    for (int o = 0; o < 4; o++) {
        make_order(ORDERS[o], values, 15, 20260710u, order);
        printf(o ? ",{" : "{");
        printf("\"order\":\"%s\",\"inserts\":[", ORDERS[o]);
        for (int i = 0; i < 15; i++) printf(i ? ",%d" : "%d", order[i]);
        printf("],\"paths\":[");
        int root = build(order, 15, 1);
        next_x = 0;
        walk(root);
        printf("],\"nodes\":[");
        for (int i = 0; i < count; i++) {
            printf(i ? ",{" : "{");
            printf("\"v\":%d,\"x\":%d,\"y\":%d,\"p\":%d}", val[i], xpos[i], depth[i],
                   parent[i] == -1 ? -1 : val[parent[i]]);
        }
        printf("],\"height\":%d,\"compares\":%d}", height(), total_compare());
    }

    /* How the shape grows: every order, from 4 to 256 values. */
    printf("],\"sweep\":[");
    int first = 1;
    for (int n = 4; n <= MAXN; n += 4) {
        for (int i = 0; i < n; i++) sorted[i] = i + 1;
        for (int o = 0; o < 4; o++) {
            make_order(ORDERS[o], sorted, n, 20260710u + (unsigned int)n, order);
            build(order, n, 0);
            printf(first ? "{" : ",{");
            first = 0;
            printf("\"n\":%d,\"order\":\"%s\",\"height\":%d,\"compares\":%d}", n, ORDERS[o], height(), total_compare());
        }
    }
    printf("]}}\n");

    printf("15 values, four insert orders:\n");
    for (int o = 0; o < 4; o++) {
        make_order(ORDERS[o], values, 15, 20260710u, order);
        build(order, 15, 0);
        printf("  %-11s height %2d, %.2f comparisons to find a value on average\n", ORDERS[o], height(), (double)total_compare() / count);
    }
    printf("256 values:\n");
    for (int i = 0; i < 256; i++) sorted[i] = i + 1;
    for (int o = 0; o < 4; o++) {
        make_order(ORDERS[o], sorted, 256, 20260710u + 256u, order);
        build(order, 256, 0);
        printf("  %-11s height %3d, %.2f comparisons\n", ORDERS[o], height(), (double)total_compare() / count);
    }
    return 0;
}

// Check the BST rule on every tree, then chart how the shape scales.
const bst = nb.get('bst');
if (!bst) return 'Run the compute cell first.';

console.log('order        height  avg comparisons  in order  sides  height ok');
for (const t of bst.trees) {
  const byV = Object.fromEntries(t.nodes.map(d => [d.v, d]));
  const inOrder = [...t.nodes].sort((a, b) => a.x - b.x).map(d => d.v);
  const ascending = inOrder.every((v, i) => i === 0 || inOrder[i - 1] < v) &&
    inOrder.join() === [...bst.values].sort((a, b) => a - b).join();
  // every node must be on the correct side of each ancestor, not just its parent
  const sides = t.nodes.every(d => {
    for (let up = byV[d.p]; up; up = byV[up.p]) {
      if ((d.x < up.x) !== (d.v < up.v)) return false;   // left of an ancestor means smaller
    }
    return true;
  });
  const heightOk = t.height === Math.max(...t.nodes.map(d => d.y)) + 1;
  console.log(t.order.padEnd(12) + String(t.height).padStart(7) + (t.compares / t.nodes.length).toFixed(2).padStart(17) +
    String(ascending).padStart(10) + String(sides).padStart(7) + String(heightOk).padStart(11));
}

const rows = bst.sweep.map(r => ({ n: r.n, order: r.order, avg: r.compares / r.n }));
for (const r of bst.sweep.filter(r => r.n === 256)) {
  console.log('256 values, ' + r.order + ': height ' + r.height + ', ' + (r.compares / r.n).toFixed(2) + ' comparisons on average');
}
for (let k = 4; k <= 256; k += 4) rows.push({ n: k, order: 'log2(n)', avg: Math.log2(k) });

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 300,
  title: 'Average comparisons to find a value, by insert order',
  data: { values: rows },
  mark: { type: 'line', strokeWidth: 2 },
  encoding: {
    x: { field: 'n', type: 'quantitative', title: 'values in the tree' },
    y: { field: 'avg', type: 'quantitative', scale: { type: 'log' }, title: 'average comparisons (log scale)' },
    color: { field: 'order', type: 'nominal', title: null,
      scale: { domain: ['balanced', 'random', 'sorted', 'alternating', 'log2(n)'],
               range: ['#22c55e', '#3b82f6', '#ef4444', '#f59e0b', '#94a3b8'] } },
    strokeDash: { condition: { test: "datum.order === 'log2(n)' || datum.order === 'alternating'", value: [5, 4] }, value: [1, 0] },
  },
};
